"use client";
import { useEffect, useState } from "react";

export default function Hero() {
  const [tick, setTick] = useState(true);

  useEffect(() => {
    const id = setInterval(() => setTick((t) => !t), 530);
    return () => clearInterval(id);
  }, []);

  return (
    <section style={s.section}>
      <div style={s.gridBg} />

      <div style={s.layout}>
        {/* COLUMNA IZQUIERDA */}
        <div style={s.left}>
          {/* Prompt terminal */}
          <div style={s.terminalLine}>
            <span style={s.prompt}>yuna@dev</span>
            <span style={s.dim}>:</span>
            <span style={s.path}>~</span>
            <span style={s.dim}>$</span>
            <span style={s.cmd}> cat about.md</span>
            <span style={{ ...s.cursor, opacity: tick ? 1 : 0 }}>█</span>
          </div>

          {/* Nombre */}
          <h1 style={s.name}>
            Yuna<br />
            <span style={s.nameOutline}>Espejo</span>
          </h1>

          {/* Disponibilidad */}
          <div style={s.tagRow}>
            <span style={s.dot} />
            <span style={s.tagText}>available for opportunities</span>
          </div>

          {/* Descripción */}
          <p style={s.desc}>
            Junior Consultant @ <span style={s.hl}>Timestamp Group.</span><br />
            Finishing <span style={s.hl}>ASIX</span> · Starting CS @{" "}
            <span style={s.hl}>UOC</span> this September.<br />
            Building data tools and motorsport visualizations.
          </p>

          {/* CTAs */}
          <div style={s.ctaRow}>
            <a href="/projects" style={s.btnPrimary}>./projects</a>
            <a href="/cv.pdf" target="_blank" rel="noreferrer" style={s.btnGhost}>
              cat cv.pdf
            </a>
          </div>
        </div>

        {/* COLUMNA DERECHA — stats */}
        <div style={s.right}>
          {[
            { label: "current role", value: "Junior Consultant", accent: true },
            { label: "stack", value: "Node · React · Canvas" },
            { label: "next milestone", value: "CS @ UOC · Sept '25", accent: true },
            { label: "focus area", value: "Software Engineering" },
          ].map(({ label, value, accent }) => (
            <div key={label} style={s.statBlock}>
              <div style={s.statLabel}>{label}</div>
              <div style={s.statValue}>
                {accent && <span style={s.accentSquare}>■ </span>}
                {value}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Barra inferior */}
      <div style={s.bottomBar}>
        <span style={s.coords}>41.3851° N, 2.1734° E — Barcelona</span>
        <span style={s.scrollHint}>scroll to explore ——</span>
      </div>
    </section>
  );
}

const GREEN = "#7fff7f";
const DIM = "rgba(255,255,255,0.22)";
const MID = "rgba(255,255,255,0.45)";
const BRIGHT = "rgba(255,255,255,0.82)";
const BORDER = "rgba(255,255,255,0.07)";

const s: Record<string, React.CSSProperties> = {
  section: {
    position: "relative",
    minHeight: "100vh",
    background: "#020617",
    overflow: "hidden",
    fontFamily: "var(--font-jetbrains), monospace",
    color: "#e8e8e8",
    display: "flex",
    flexDirection: "column",
  },
  gridBg: {
    position: "absolute",
    inset: 0,
    backgroundImage:
      "linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px)," +
      "linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px)",
    backgroundSize: "40px 40px",
    pointerEvents: "none",
  },

  /* Grid de dos columnas */
  layout: {
    position: "relative",
    zIndex: 2,
    flex: 1,
    display: "grid",
    gridTemplateColumns: "1fr 260px",
    gap: "2rem",
    alignItems: "center",
    padding: "6rem 3rem 5rem",
  },

  left: {
    display: "flex",
    flexDirection: "column",
    gap: 0,
  },

  right: {
    display: "flex",
    flexDirection: "column",
    gap: "1px",
    alignSelf: "center",
  },

  /* Terminal */
  terminalLine: {
    fontSize: "13px",
    letterSpacing: "0.04em",
    display: "flex",
    alignItems: "center",
    marginBottom: "1.25rem",
  },
  prompt: { color: GREEN },
  dim: { color: DIM },
  path: { color: "#5b9bd5" },
  cmd: { color: MID },
  cursor: { color: GREEN, marginLeft: "3px", transition: "opacity 0.1s" },

  /* Nombre */
  name: {
    fontFamily: "var(--font-montserrat), sans-serif",
    fontSize: "clamp(44px, 6.5vw, 80px)",
    fontWeight: 900,
    lineHeight: 1.0,
    letterSpacing: "-0.02em",
    color: "#ffffff",
    margin: "0 0 1.25rem",
    padding: 0,
  },
  nameOutline: {
  color: "rgba(255,255,255,0.18)",
  },
  
  /* Tag */
  tagRow: {
    display: "flex",
    alignItems: "center",
    gap: "0.5rem",
    marginBottom: "1rem",
  },
  dot: {
    width: "7px",
    height: "7px",
    borderRadius: "50%",
    background: GREEN,
    flexShrink: 0,
    animation: "pulse 2s ease-in-out infinite",
  },
  tagText: {
    fontSize: "11px",
    color: GREEN,
    letterSpacing: "0.1em",
    textTransform: "uppercase",
  },

  /* Descripción */
  desc: {
    fontSize: "14px",
    color: MID,
    lineHeight: 1.9,
    maxWidth: "400px",
    margin: "0 0 2rem",
    padding: 0,
  },
  hl: { color: BRIGHT },

  /* CTAs */
  ctaRow: {
    display: "flex",
    gap: "1rem",
    flexWrap: "wrap",
  },
  btnPrimary: {
    background: GREEN,
    color: "#020617",
    fontFamily: "var(--font-jetbrains), monospace",
    fontSize: "12px",
    fontWeight: 700,
    letterSpacing: "0.08em",
    textTransform: "uppercase",
    padding: "0.75rem 1.5rem",
    textDecoration: "none",
    display: "inline-block",
  },
  btnGhost: {
    background: "transparent",
    color: MID,
    fontFamily: "var(--font-jetbrains), monospace",
    fontSize: "12px",
    letterSpacing: "0.08em",
    textTransform: "uppercase",
    padding: "0.75rem 1.5rem",
    border: `1px solid ${BORDER}`,
    textDecoration: "none",
    display: "inline-block",
  },

  /* Stats */
  statBlock: {
    border: `1px solid ${BORDER}`,
    padding: "1rem 1.25rem",
    background: "rgba(255,255,255,0.02)",
  },
  statLabel: {
    fontSize: "10px",
    color: DIM,
    letterSpacing: "0.12em",
    textTransform: "uppercase",
    marginBottom: "0.3rem",
  },
  statValue: {
    fontSize: "13px",
    color: BRIGHT,
  },
  accentSquare: { color: GREEN },

  /* Bottom bar */
  bottomBar: {
    position: "relative",
    zIndex: 2,
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    padding: "1rem 3rem",
    borderTop: `1px solid ${BORDER}`,
  },
  coords: {
    fontSize: "11px",
    color: "rgba(255,255,255,0.15)",
    letterSpacing: "0.06em",
  },
  scrollHint: {
    fontSize: "11px",
    color: "rgba(255,255,255,0.15)",
    letterSpacing: "0.1em",
  },
};